use serde_json::{json,Value};use sha2::{Digest,Sha256};
use std::{collections::{BTreeMap,BTreeSet},fs,path::{Path,PathBuf},process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/three-lane-miller176";
const F:&str="/home/ubuntu/src/zopro-perf-work/g2-vector-sign-default175/frozen/candidate";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){assert!(!p.as_ref().exists());fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn step(n:impl Into<String>,a:Vec<String>)->Value{json!({"kind":"command","name":n.into(),"argv":a,"timeout_seconds":300,"environment":{"LC_ALL":"C"}})}
fn add(arm:&str,endpoint:&str,w:usize,block:usize,panel:&str,jobs:&mut Vec<Value>,steps:&mut Vec<Value>){
 let name=format!("{panel}-b{block}-{endpoint}-w{w}-{arm}");let rounds=if panel=="preflight"{1}else if panel=="latency"{31}else{8192};let affinity=if w==1{"2".to_string()}else{format!("0-{}",w-1)};let mut argv=vec![];let mut data=None;
 if panel=="stat"||panel=="profile"{
  argv.extend(["sudo".into(),"-n".into(),"env".into(),"LC_ALL=C".into(),format!("ZOPRO_BENCH_PERF_CTL={}",r("ctl").display()),format!("ZOPRO_BENCH_PERF_ACK={}",r("ack").display()),"perf".into()]);
  if panel=="stat"{let f=r(format!("stat/{name}.csv"));argv.extend(["stat".into(),"--no-big-num".into(),"-x".into(),";".into(),"-e".into(),"{cycles:u,instructions:u}".into(),"-e".into(),"page-faults,context-switches".into(),"-o".into(),f.display().to_string()]);data=Some(f);}
  else{let f=r(format!("perf/{name}.data"));argv.extend(["record".into(),"--no-buildid-cache".into(),"--sample-cpu".into(),"--timestamp".into(),"-P".into(),"-e".into(),"cycles:u".into(),"-c".into(),"4000000".into(),"-m".into(),"512".into(),"-o".into(),f.display().to_string()]);data=Some(f);}
  argv.extend(["--delay=-1".into(),format!("--control=fifo:{},{}",r("ctl").display(),r("ack").display()),"--".into()]);
 }
 argv.extend(["taskset".into(),"-c".into(),affinity,r("bench").display().to_string(),arm.into(),endpoint.into(),w.to_string(),rounds.to_string()]);steps.push(step(&name,argv));jobs.push(json!({"name":name,"arm":arm,"endpoint":endpoint,"workers":w,"block":block,"panel":panel,"rounds":rounds,"data":data}));
}
fn prepare(){
 assert_eq!(read(r("qualification.json"))["passed"],true);let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r("qualification-pins.json"))).unwrap();for(p,h)in &pins{assert_eq!(hash(p),*h);}
 for p in [r("bench.rs"),r("bench"),r("timing-design.md"),r("campaign.rs"),r("campaign"),r("publish.rs"),r("publish"),r("synthetic-fixtures.json"),r("qualification.json"),r("qualification-runs/packed-extension-and-Miller-qualification/exit.json"),PathBuf::from("/home/ubuntu/src/zopro-perf-work/g2-last-finisher-query176/perf_support.rs")]{pins.insert(p.display().to_string(),hash(p));}
 for e in fs::read_dir(F).unwrap(){let p=e.unwrap().path();if p.extension().and_then(|p|p.to_str())==Some("rlib"){pins.insert(p.display().to_string(),hash(p));}}
 for(program,args,name)in[("nm",vec!["-S","-C","--defined-only"],"bench.nm"),("objdump",vec!["-d","-C"],"bench.asm")]{let o=Command::new(program).args(args).arg(r("bench")).output().unwrap();assert!(o.status.success());fs::write(r(name),o.stdout).unwrap();pins.insert(r(name).display().to_string(),hash(r(name)));}
 let asm=fs::read_to_string(r("bench.asm")).unwrap();assert!(asm.contains("madd52")&&asm.contains("packed::")&&asm.contains("%zmm"));
 for d in["perf","stat"]{fs::create_dir(r(d)).unwrap();}for n in["ctl","ack"]{assert!(Command::new("mkfifo").args(["-m","600"]).arg(r(n)).status().unwrap().success());}assert!(Command::new("sudo").args(["-n","true"]).status().unwrap().success());
 let mut jobs=vec![];let mut steps=vec![];let cases=[("miller",1usize),("miller",16),("miller",32),("full",1),("full",16),("full",32)];
 for(ep,w)in cases{for arm in["native","fresh","packed"]{add(arm,ep,w,0,"preflight",&mut jobs,&mut steps);}}
 steps.push(step("validate-preflights",vec![r("campaign").display().to_string(),"preflights".into()]));
 for block in 0..15{let mut order=(0..6).collect::<Vec<_>>();order.rotate_left(block%6);let mut arms=["native","fresh","packed"];arms.rotate_left(block%3);if block%2!=0{order.reverse();arms.reverse();}for i in order{let(ep,w)=cases[i];for arm in arms{add(arm,ep,w,block,"latency",&mut jobs,&mut steps);}if w!=1{add("serial",ep,w,block,"latency",&mut jobs,&mut steps);}}}
 for panel in["stat","profile"]{for w in[1usize,32]{for arm in["native","packed"]{add(arm,"full",w,0,panel,&mut jobs,&mut steps);}}}
 let uid=Command::new("id").arg("-u").output().unwrap();let gid=Command::new("id").arg("-g").output().unwrap();assert!(uid.status.success()&&gid.status.success());let owner=format!("{}:{}",String::from_utf8(uid.stdout).unwrap().trim(),String::from_utf8(gid.stdout).unwrap().trim());
 for j in jobs.iter().filter(|j|j["data"].is_string()){let name=j["name"].as_str().unwrap();let data=j["data"].as_str().unwrap();steps.push(step(format!("own-{name}"),vec!["sudo".into(),"-n".into(),"chown".into(),owner.clone(),data.into()]));}
 for j in jobs.iter().filter(|j|j["panel"]=="profile"){let name=j["name"].as_str().unwrap();let data=j["data"].as_str().unwrap();steps.push(step(format!("report-{name}"),vec!["perf".into(),"report".into(),"--stdio".into(),"--no-children".into(),"--percent-limit".into(),"0".into(),"--sort".into(),"dso,symbol".into(),"-i".into(),data.into()]));steps.push(step(format!("samples-{name}"),vec!["perf".into(),"script".into(),"-i".into(),data.into(),"-F".into(),"comm,pid,tid,cpu,time,event,period,ip,sym,dso".into()]));steps.push(step(format!("raw-{name}"),vec!["perf".into(),"script".into(),"-D".into(),"-i".into(),data.into()]));}
 save(r("jobs.json"),&json!(jobs));save(r("capture-pins.json"),&json!(pins));save(r("capture-plan.json"),&json!({"version":1,"source_pins":r("capture-pins.json"),"steps":steps}));println!("Prepared {} jobs, {} commands, {} pins; no timed call yet",jobs.len(),steps.len(),pins.len());
}
fn output(j:&Value)->Value{let n=j["name"].as_str().unwrap();let base=r(format!("capture/{n}"));let exit=read(base.join("exit.json"));assert_eq!(exit["success"],true);for(s,k)in[("stdout.log","stdout_sha256"),("stderr.log","stderr_sha256")]{assert_eq!(hash(base.join(s)),exit[k].as_str().unwrap());}let text=fs::read_to_string(base.join("stdout.log")).unwrap();let row=text.lines().filter_map(|l|serde_json::from_str::<Value>(l).ok()).find(|v|v["samples_ns"].is_array()).unwrap();for k in["arm","endpoint","workers","rounds"]{assert_eq!(row[k],j[k]);}assert_eq!(row["checked_outputs"],j["rounds"]);assert_eq!(row["worker_pins"].as_array().unwrap().len(),j["workers"].as_u64().unwrap()as usize);let mut ns=row["samples_ns"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()).collect::<Vec<_>>();assert_eq!(ns.len(),j["rounds"].as_u64().unwrap()as usize);ns.sort_unstable();assert_eq!(row["median_ns"],ns[ns.len()/2]);row}
fn preflights(){let jobs=read(r("jobs.json"));let mut digests=BTreeMap::<String,BTreeSet<String>>::new();for j in jobs.as_array().unwrap().iter().filter(|j|j["panel"]=="preflight"){let row=output(j);digests.entry(j["endpoint"].as_str().unwrap().into()).or_default().insert(row["output_sha256"].as_str().unwrap().into());}assert!(digests.values().all(|v|v.len()==1));save(r("preflights.json"),&json!({"passed":true,"contexts":6,"arms":3,"processes":18}));println!("All eighteen final-consumer preflights match cached full-output oracles");}
fn interval(mut v:Vec<f64>)->Value{assert_eq!(v.len(),15);let wins=v.iter().filter(|&&v|v<1.).count();v.sort_by(|a,b|a.total_cmp(b));json!({"median":v[7],"low":v[3],"high":v[11],"wins":wins})}
fn finish(){
 assert_eq!(read(r("capture/result.json"))["status"],"complete");for(p,h)in read(r("capture-pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}
 let jobs=read(r("jobs.json"));let jobs=jobs.as_array().unwrap();let mut table=BTreeMap::<(String,usize,String,usize),Value>::new();let mut all=vec![];
 for j in jobs{let out=output(j);if j["panel"]=="latency"{table.insert((j["endpoint"].as_str().unwrap().into(),j["workers"].as_u64().unwrap()as usize,j["arm"].as_str().unwrap().into(),j["block"].as_u64().unwrap()as usize),out.clone());}all.push(json!({"job":j,"observation":out}));}
 let mut contexts=vec![];let mut failures=vec![];let mut aggregate=BTreeMap::from([("native",vec![0f64;15]),("fresh",vec![0f64;15])]);
 let at=|ep:&str,w:usize,arm:&str,b:usize|table[&(ep.into(),w,arm.into(),b)]["median_ns"].as_u64().unwrap()as f64;
 for ep in["miller","full"]{for w in[1usize,16,32]{let cal=interval((0..15).map(|b|at(ep,w,"fresh",b)/at(ep,w,"native",b)).collect());if cal["low"].as_f64().unwrap()<1./1.03||cal["high"].as_f64().unwrap()>1.03{failures.push(format!("calibration {ep} w{w}"));}
  let mut row=json!({"endpoint":ep,"workers":w,"calibration_fresh_native":cal});for arm in["native","fresh","packed"]{let mut ms=(0..15).map(|b|at(ep,w,arm,b)).collect::<Vec<_>>();ms.sort_by(|a,b|a.total_cmp(b));row[format!("{arm}_median_ns")]=json!(ms[7]);}
  for control in["native","fresh"]{let ratios=(0..15).map(|b|at(ep,w,"packed",b)/at(ep,w,control,b)).collect::<Vec<_>>();for b in 0..15{aggregate.get_mut(control).unwrap()[b]+=ratios[b].ln()/6.;}let ci=interval(ratios);if ci["high"].as_f64().unwrap()>1.03{failures.push(format!("nonregression {ep} w{w}/{control}"));}if ep=="full"&&w==32&&(ci["high"].as_f64().unwrap()>=1.||ci["wins"].as_u64().unwrap()<10){failures.push(format!("gain full w32/{control}"));}row[format!("packed_{control}")]=ci;}
  if w!=1{let mut v=(0..15).map(|b|at(ep,w,"serial",b)).collect::<Vec<_>>();v.sort_by(|a,b|a.total_cmp(b));row["serial_median_ns"]=json!(v[7]);}contexts.push(row);
 }}
 let mut aggregates=json!({});for control in["native","fresh"]{let ci=interval(aggregate.remove(control).unwrap().into_iter().map(f64::exp).collect());if ci["high"].as_f64().unwrap()>=1.||ci["wins"].as_u64().unwrap()<10{failures.push(format!("gain all6/{control}"));}aggregates[control]=ci;}
 let mut profiles=vec![];for j in jobs.iter().filter(|j|j["panel"]=="profile"){let n=j["name"].as_str().unwrap();let raw=fs::read_to_string(r(format!("capture/raw-{n}/stdout.log"))).unwrap();let samples=fs::read_to_string(r(format!("capture/samples-{n}/stdout.log"))).unwrap();let lost=raw.lines().filter(|l|l.contains("PERF_RECORD_LOST")).count();let lines=samples.lines().filter(|l|l.contains("cycles:u")).collect::<Vec<_>>();let unknown=lines.iter().filter(|l|l.contains("[unknown]")).count();profiles.push(json!({"job":n,"samples":lines.len(),"unknown_samples":unknown,"unknown_fraction":unknown as f64/lines.len().max(1)as f64,"lost_records":lost,"zero_lost":lost==0,"at_least_1000_samples":lines.len()>=1000,"data_sha256":hash(j["data"].as_str().unwrap()),"report":format!("capture/report-{n}/stdout.log"),"parser_scope":"single simple stream counter; no exact ELF/IP/TID/period reparser"}));}
 save(r("observations.json"),&json!(all));save(r("analysis.json"),&json!({"gate_passed":failures.is_empty(),"failed_checks":failures,"contexts":contexts,"all6":aggregates,"profiles":profiles,"new_component_processes":jobs.len(),"qualified_source_unchanged":true,"new_SDK_requests":0,"new_proofs":0,"production_changed":false,"candidate_adopted":false,"proof_ledger_count":31387}));println!("Complete fixed caller capture; gate={}, {}failed checks",failures.is_empty(),failures.len());
}
fn main(){match std::env::args().nth(1).as_deref(){Some("prepare")=>prepare(),Some("preflights")=>preflights(),Some("finish")=>finish(),_=>panic!("prepare | preflights | finish")}}
